from pathlib import Path
import re

js_path=Path('despesas-reembolsos-v2.js')
html_path=Path('despesas-reembolsos-v2.html')
js=js_path.read_text(encoding='utf-8')
html=html_path.read_text(encoding='utf-8')

old="let token='',B=null,events=[],expenses=[],reimbursements=[],agenda=[],cards=[],banks=[],geo=null,fiscal={},qrScanner=null,sortKey='incurred_at',sortDir=-1,catalogTab='category';"
new="let token='',B=null,events=[],expenses=[],reimbursements=[],agenda=[],cards=[],banks=[],shareCandidates=[],geo=null,fiscal={},qrScanner=null,sortKey='incurred_at',sortDir=-1,catalogTab='category';"
if old not in js: raise SystemExit('globals not found')
js=js.replace(old,new,1)

old="document.querySelector('[data-v=\"catalogs\"]').classList.toggle('hidden',!p.admin);"
new="document.querySelector('[data-v=\"catalogs\"]').classList.remove('hidden');"
if old not in js: raise SystemExit('catalog visibility not found')
js=js.replace(old,new,1)

old="cards=c.cards||[];banks=c.banks||[];renderHome(d);"
new="cards=c.cards||[];banks=c.banks||[];shareCandidates=c.share_candidates||[];renderHome(d);"
if old not in js: raise SystemExit('reload card payload not found')
js=js.replace(old,new,1)

old="function cardLabel(c){return `${c.nickname} · •••• ${c.last4} · ${cardModeLabel(c)}${c.card_type==='EMPRESA'?' · Empresa':c.owner_name?' · '+c.owner_name:''}`}"
new="function cardLabel(c){return `${c.nickname} · •••• ${c.last4} · ${cardModeLabel(c)}${c.card_type==='EMPRESA'?' · Empresa':c.owner_name?' · '+c.owner_name:''}`}\nfunction expenseCardLabel(x){const c=by(cards,x?.card_id,'card_id');return c?cardLabel(c):String(x?.card_alias||'').trim()}"
if old not in js: raise SystemExit('cardLabel not found')
js=js.replace(old,new,1)

old="const rows=cards.filter(c=>{const ownerOk=c.card_type==='EMPRESA'?c.company_key===companyKey:String(c.owner_user_id)===paidBy,mode=String(c.payment_mode||'AMBOS').toUpperCase(),modeOk=(!wantsCredit&&!wantsDebit)||mode==='AMBOS'||(wantsCredit&&mode==='CREDITO')||(wantsDebit&&mode==='DEBITO');return ownerOk&&modeOk});"
new="const rows=cards.filter(c=>{const ownerOk=c.card_type==='EMPRESA'?c.company_key===companyKey:String(c.owner_user_id)===paidBy,mode=String(c.payment_mode||'AMBOS').toUpperCase(),modeOk=(!wantsCredit&&!wantsDebit)||mode==='AMBOS'||(wantsCredit&&mode==='CREDITO')||(wantsDebit&&mode==='DEBITO');return c.can_use!==false&&ownerOk&&modeOk});"
if old not in js: raise SystemExit('renderCardOptions rows not found')
js=js.replace(old,new,1)

# Historical expense shows full card detail only when current user can see that card; otherwise only the saved alias.
old="${x.card_id?' · <b>Cartão:</b> '+esc(cardLabel(by(cards,x.card_id,'card_id')||{nickname:'Cartão',last4:'????',card_type:'PESSOAL'})):''}"
new="${expenseCardLabel(x)?' · <b>Cartão:</b> '+esc(expenseCardLabel(x)):''}"
if old not in js: raise SystemExit('expense card history block not found')
js=js.replace(old,new,1)

# Replace catalog renderer: non-admins get only Cards; card management buttons respect can_manage.
pattern=r"function renderCatalogs\(\)\{.*?\}\nasync function refreshAdminData"
replacement=r'''function renderCatalogs(){const allDefs=catalogDefs(),defs=B.permissions.admin?allDefs:[],valid=B.permissions.admin?[...defs.map(x=>x.type),'cards']:['cards'];if(!valid.includes(catalogTab))catalogTab='cards';const tabs=(B.permissions.admin?defs.map(d=>`<button class="catalog-tab ${catalogTab===d.type?'active':''}" data-cat-tab="${d.type}">${d.label}</button>`).join(''):'')+`<button class="catalog-tab ${catalogTab==='cards'?'active':''}" data-cat-tab="cards">Cartões</button>`;let panel='';if(catalogTab==='cards'){const visible=cards.filter(c=>c.card_type==='PESSOAL'||!currentCompany()||c.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>Cartões</h3><small>Cartão pessoal é privado. Cartões da empresa aparecem somente para quem recebeu acesso.</small></div><button class="btn" id="addPersonalCard">+ Pessoal</button>${B.permissions.admin?'<button class="btn primary" id="addCompanyCard">+ Empresa</button>':''}</div>${visible.map(c=>`<div class="catalog-row"><div><b>${esc(c.nickname)} · •••• ${esc(c.last4)}</b><small>${c.card_type==='EMPRESA'?esc(company(c.company_key))+' · corporativo':esc(c.owner_name||'Pessoal')} · ${esc(cardModeLabel(c))}${c.brand?' · '+esc(c.brand):''}${bankLabel(c)?' · '+esc(bankLabel(c)):''}${c.card_type==='EMPRESA'&&Array.isArray(c.shared_user_ids)&&c.shared_user_ids.length?' · compartilhado com '+c.shared_user_ids.length+' pessoa(s)':''}</small></div><div class="catalog-row-actions">${c.can_manage!==false?`<button class="btn" data-card-edit="${c.card_id}">Editar</button><button class="btn bad" data-card-del="${c.card_id}">Excluir</button>`:'<span class="chip">Compartilhado comigo</span>'}</div></div>`).join('')||'<div class="empty">Nenhum cartão cadastrado.</div>'}</div>`}else{const d=defs.find(x=>x.type===catalogTab);if(!d){catalogTab='cards';return renderCatalogs()}const rows=d.rows.filter(x=>!currentCompany()||x.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>${d.label}</h3><small>${rows.length} cadastro(s) ativo(s)</small></div><button class="btn primary" data-add="${d.type}">+ Adicionar</button></div>${rows.map(x=>`<div class="catalog-row"><div><b>${esc(x.name)}</b><small>${esc(company(x.company_key))}${x.code?' · '+esc(x.code):''}${x.description?' · '+esc(x.description):''}</small></div><div class="catalog-row-actions"><button class="btn" data-cat-edit="${d.type}" data-id="${x[d.id]}">Editar</button><button class="btn bad" data-cat-del="${d.type}" data-id="${x[d.id]}">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhum cadastro nesta seção.</div>'}</div>`}$('catalogGrid').innerHTML=`<div class="catalog-manager"><div class="catalog-tabs">${tabs}</div>${panel}</div>`;document.querySelectorAll('[data-cat-tab]').forEach(b=>b.onclick=()=>{catalogTab=b.dataset.catTab;renderCatalogs()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>catalogForm(b.dataset.add));document.querySelectorAll('[data-cat-edit]').forEach(b=>{b.onclick=()=>{const d=defs.find(x=>x.type===b.dataset.catEdit),item=d.rows.find(x=>String(x[d.id])===String(b.dataset.id));catalogForm(d.type,item)}});document.querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=()=>deleteCatalog(b.dataset.catDel,b.dataset.id));if($('addPersonalCard'))$('addPersonalCard').onclick=()=>cardForm('PESSOAL');if($('addCompanyCard'))$('addCompanyCard').onclick=()=>cardForm('EMPRESA');document.querySelectorAll('[data-card-edit]').forEach(b=>b.onclick=()=>{const c=by(cards,b.dataset.cardEdit,'card_id');cardForm(c.card_type,c)});document.querySelectorAll('[data-card-del]').forEach(b=>b.onclick=()=>deleteCard(b.dataset.cardDel))}
async function refreshAdminData'''
js,n=re.subn(pattern,lambda m:replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'renderCatalogs replacement count={n}')

# Replace card form adding share checkboxes for company cards while keeping bank/brand features.
pattern=r"function cardForm\(type,item=null\)\{.*?\}\nasync function deleteCard"
replacement=r'''function cardForm(type,item=null){const brandList=['Visa','Mastercard','Elo','American Express','Hipercard'],currentBrand=String(item?.brand||''),knownBrand=brandList.some(x=>x.toLowerCase()===currentBrand.toLowerCase()),bankOptions=(banks||[]).map(b=>`<option value="${esc(b.bank_code)}">${esc(b.bank_code)} — ${esc(b.name)}</option>`).join(''),shared=new Set((item?.shared_user_ids||[]).map(String)),shareRows=(shareCandidates||[]).filter(u=>String(u.id)!==String(B.user.id)&&String(u.id)!==String(item?.created_by_user_id||''));$('modalTitle').textContent=item?'Editar cartão':type==='EMPRESA'?'Novo cartão da empresa':'Novo cartão pessoal';$('modalBody').innerHTML=`<div class="form">${type==='EMPRESA'?`<div class="field"><label>Empresa *</label><select id="cardCompany">${opts(B.companies,'key','name')}</select></div>`:''}<div class="field"><label>Apelido *</label><input id="cardNick" placeholder="Ex.: Itaú Black" value="${esc(item?.nickname||'')}"></div><div class="field"><label>Modalidade *</label><select id="cardPaymentMode"><option value="CREDITO">Crédito</option><option value="DEBITO">Débito</option><option value="AMBOS">Crédito e Débito</option></select></div><div class="field"><label>Número ou 4 finais *</label><input id="cardNumber" inputmode="numeric" autocomplete="off" placeholder="Número do cartão ou últimos 4 dígitos" value="${esc(item?.last4||'')}"><small>O sistema guarda somente os últimos 4 dígitos.</small></div><div class="field"><label>Banco / emissor</label><select id="cardBank"><option value="">Selecione o banco…</option>${bankOptions}<option value="__NEW__">+ Adicionar outro banco</option></select></div><div id="newBankWrap" class="field full hidden"><div class="form"><div class="field"><label>Código do banco *</label><input id="newBankCode" inputmode="numeric" maxlength="3" placeholder="Ex.: 260"></div><div class="field"><label>Nome do banco *</label><input id="newBankName" placeholder="Nome da instituição"></div></div><small>O banco será salvo e ficará disponível nos próximos cartões.</small></div><div class="field"><label>Bandeira</label><select id="cardBrand"><option value="">Selecione a bandeira…</option>${brandList.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}<option value="__OTHER__">Outra bandeira…</option></select></div><div id="otherBrandWrap" class="field hidden"><label>Outra bandeira</label><input id="otherBrand" placeholder="Nome da bandeira" value="${esc(!knownBrand?currentBrand:'')}"></div>${type==='EMPRESA'?`<div class="field full"><label>Quem pode usar este cartão?</label><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:7px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#fafcff">${shareRows.map(u=>`<label style="display:flex;align-items:center;gap:7px"><input type="checkbox" data-card-share value="${u.id}" ${shared.has(String(u.id))?'checked':''}> <span>${esc(u.name)}</span></label>`).join('')||'<small>Nenhum outro sócio disponível.</small>'}</div><small>Somente as pessoas marcadas poderão selecionar este cartão em novas despesas. Você, como responsável pelo cartão, mantém acesso automaticamente.</small></div>`:'<div class="field full"><div class="payment-note"><b>Privado:</b> este cartão pessoal só aparecerá para você. Em despesas já registradas, outros usuários autorizados a ver a despesa verão apenas o apelido do cartão.</div></div>'}</div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveCard">Salvar</button>';showModal();if($('cardCompany')){$('cardCompany').value=item?.company_key||currentCompany()||B.companies[0]?.key||'';if(item)$('cardCompany').disabled=true}$('cardPaymentMode').value=String(item?.payment_mode||'AMBOS').toUpperCase();$('cardBank').value=(banks||[]).some(b=>String(b.bank_code)===String(item?.bank_code||''))?String(item.bank_code):'';$('cardBrand').value=knownBrand?brandList.find(x=>x.toLowerCase()===currentBrand.toLowerCase()):currentBrand?'__OTHER__':'';const toggleBank=()=>$('newBankWrap').classList.toggle('hidden',$('cardBank').value!=='__NEW__'),toggleBrand=()=>$('otherBrandWrap').classList.toggle('hidden',$('cardBrand').value!=='__OTHER__');$('cardBank').onchange=toggleBank;$('cardBrand').onchange=toggleBrand;toggleBank();toggleBrand();$('modalClose').onclick=hideModal;$('saveCard').onclick=async()=>{let bankCode=$('cardBank').value;if(bankCode==='__NEW__'){const code=digits($('newBankCode').value),name=$('newBankName').value.trim();if(code.length!==3)return alert('Informe o código do banco com 3 dígitos.');if(!name)return alert('Informe o nome do banco.');const br=await cardApi('/banks',{method:'POST',body:JSON.stringify({bank_code:code,name})});bankCode=br.bank?.bank_code||code}const brand=$('cardBrand').value==='__OTHER__'?$('otherBrand').value.trim():$('cardBrand').value,sharedIds=type==='EMPRESA'?[...document.querySelectorAll('[data-card-share]:checked')].map(x=>Number(x.value)):[];await cardApi('/cards',{method:'POST',body:JSON.stringify({card_id:item?.card_id||null,card_type:type,company_key:$('cardCompany')?.value||item?.company_key||null,nickname:$('cardNick').value,last4:$('cardNumber').value,brand:brand||null,bank_code:bankCode||null,payment_mode:$('cardPaymentMode').value,shared_user_ids:sharedIds})});hideModal();await reload();renderCatalogs();renderCardOptions();flash(item?'Cartão atualizado.':'Cartão cadastrado.')}}
async function deleteCard'''
js,n=re.subn(pattern,lambda m:replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'cardForm replacement count={n}')

html=re.sub(r'\.\/despesas-reembolsos-v2\.js\?v=\d+', './despesas-reembolsos-v2.js?v=14', html)
js_path.write_text(js,encoding='utf-8')
html_path.write_text(html,encoding='utf-8')
print('Card sharing, personal privacy and historical alias applied')
